-- scripts/add_nag_hammadi_clusters.sql
-- Nag Hammadi verify-and-add pass, batches 2-4 (Gospel of the Egyptians NHC III,2;
-- Apocryphon of John NHC II,1; Paraphrase of Shem NHC VII,1). Same method as
-- add_nag_hammadi_sethian.sql: real verbatim excerpts substring-gated against the
-- Robinson NHL text (gnosis.org), extracted via cite_anchor.py, trimmed to a
-- clause/sentence boundary. Flagged needs_review. No AI-written descriptions.

BEGIN;

ON CONFLICT (entity_id) DO NOTHING;

SELECT 'ENT_SET_HARMAS','Armas','variant','en','SRC_NAG_HAMMADI_SCRIPTURES','high','candidate_verified_name','Variant spelling attested in the same tractate.' WHERE NOT EXISTS (SELECT 1 FROM entity_aliases WHERE entity_id='ENT_SET_HARMAS' AND alias_name='Armas');

ON CONFLICT (citation_id) DO UPDATE SET quote=EXCLUDED.quote, locus=EXCLUDED.locus, source_url=EXCLUDED.source_url, verify_method=EXCLUDED.verify_method;

COMMIT;
